#!/usr/bin/env python3
"""Offline selective header-compression engine: replay and admission planning.

Implements the selective, checked dictionary compression protocol v1.1
described in PROTOCOL.md: JSON line framing, control-plane table lifecycle,
MPLS wire encoding with TTL forwarding, IP fallback, and an exact capacity
constrained admission planner.
"""

import json
import re
import sys
from operator import itemgetter

_MAX_LINE = 16 * 1024 * 1024
_MAX_PACKET_BYTES = 2 * 1024 * 1024
_INPUT_ERROR = {"error": "input"}
_OK = {"status": "ok"}
_BUSY = {"status": "busy"}
_FULL = {"status": "full"}
_UNREADY = {"status": "unready"}

_ID_RE = re.compile(r"[A-Za-z0-9_.-]{1,32}")
_HEX_RE = re.compile(r"[0-9a-f]*")
_KIND_RE = re.compile(r"[KDZQT]*")


class Bad(Exception):
    """Raised for any malformed line / schema violation."""


# ---------------------------------------------------------------- JSON framing

def _pairs_hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Bad("duplicate key")
        d[k] = v
    return d


def _bad_constant(name):
    raise Bad("non-finite number")


def _load_object(text):
    try:
        obj = json.loads(text, object_pairs_hook=_pairs_hook,
                         parse_constant=_bad_constant)
    except Bad:
        raise
    except Exception:
        raise Bad("bad json")
    if obj.__class__ is not dict:
        raise Bad("not an object")
    return obj


def _hex_bytes(value):
    if value.__class__ is not str:
        raise Bad("hex not a string")
    if _HEX_RE.fullmatch(value) is None:
        raise Bad("hex charset")
    if len(value) & 1:
        raise Bad("hex odd length")
    return bytes.fromhex(value)


def _id_str(value):
    if value.__class__ is not str or _ID_RE.fullmatch(value) is None:
        raise Bad("bad id")
    return value


def _int_in(value, lo, hi):
    if value.__class__ is not int or value < lo or value > hi:
        raise Bad("bad int")
    return value


# ------------------------------------------------------------------- flow model

class Flow(object):
    __slots__ = ("id", "path", "nodeset", "pidx", "labels", "N", "h", "tmpl",
                 "H", "kinds", "nd", "kmask", "tmplm", "dpos", "dpos0",
                 "zpos", "qpos", "tpos", "dget", "labelwords")


def _build_flow(spec, cap_nodes, with_labels):
    if spec.__class__ is not dict:
        raise Bad("flow not object")
    need = {"id", "path", "template", "kinds"}
    if with_labels:
        need.add("labels")
    if set(spec) != need:
        raise Bad("flow keys")
    fid = _id_str(spec["id"])

    path = spec["path"]
    if path.__class__ is not list:
        raise Bad("path not list")
    n = len(path)
    if n < 2 or n > 9:
        raise Bad("path length")
    nodeset = set()
    for node in path:
        _id_str(node)
        if node in nodeset or node not in cap_nodes:
            raise Bad("path node")
        nodeset.add(node)

    tmpl_hex = spec["template"]
    if tmpl_hex.__class__ is not str:
        raise Bad("template not string")
    if _HEX_RE.fullmatch(tmpl_hex) is None or (len(tmpl_hex) & 1):
        raise Bad("template hex")
    H = len(tmpl_hex) >> 1
    if H < 8 or H > 256:
        raise Bad("template size")
    tmpl = bytes.fromhex(tmpl_hex)

    kinds = spec["kinds"]
    if kinds.__class__ is not str or len(kinds) != H:
        raise Bad("kinds length")
    if _KIND_RE.fullmatch(kinds) is None:
        raise Bad("kinds charset")
    if kinds.count("Q") != 1 or kinds.count("T") != 1:
        raise Bad("kinds Q/T")
    ndyn = kinds.count("D")
    if kinds.count("K") < 1:
        raise Bad("kinds K")
    if 4 + ndyn >= H:
        raise Bad("kinds D bound")

    labels = None
    if with_labels:
        raw = spec["labels"]
        if raw.__class__ is not list or len(raw) != n:
            raise Bad("labels length")
        labels = []
        for lab in raw:
            if lab.__class__ is not int or lab < 16 or lab > 1048575:
                raise Bad("label range")
            labels.append(lab)

    fl = Flow()
    fl.id = fid
    fl.path = path
    fl.nodeset = nodeset
    fl.pidx = {node: i for i, node in enumerate(path)}
    fl.labels = labels
    fl.N = n
    fl.h = n - 1
    fl.tmpl = tmpl
    fl.H = H
    fl.kinds = kinds
    fl.nd = ndyn
    fl.qpos = kinds.index("Q")
    fl.tpos = kinds.index("T")
    fl.dpos = [i for i, c in enumerate(kinds) if c == "D"]
    fl.zpos = [i for i, c in enumerate(kinds) if c == "Z"]
    fl.dpos0 = fl.dpos[0] if fl.dpos else -1
    fl.dget = itemgetter(*fl.dpos) if ndyn > 1 else None
    mask = bytes(255 if c == "K" else 0 for c in kinds)
    fl.kmask = int.from_bytes(mask, "big")
    fl.tmplm = int.from_bytes(tmpl, "big") & fl.kmask
    fl.labelwords = [lab << 12 for lab in labels] if labels is not None else None
    return fl


def _parse_caps(value):
    if value.__class__ is not dict:
        raise Bad("capacities not object")
    if len(value) < 1 or len(value) > 64:
        raise Bad("capacities size")
    caps = {}
    for key, val in value.items():
        _id_str(key)
        if val.__class__ is not int or val < 0 or val > 512:
            raise Bad("capacity range")
        caps[key] = val
    return caps


def _parse_flows(value, caps, with_labels, limit):
    if value.__class__ is not list:
        raise Bad("flows not list")
    if len(value) > limit:
        raise Bad("flows size")
    flows = []
    seen = set()
    for spec in value:
        fl = _build_flow(spec, caps, with_labels)
        if fl.id in seen:
            raise Bad("duplicate flow id")
        seen.add(fl.id)
        flows.append(fl)
    return flows, seen


# ------------------------------------------------------------------- replay mode

def _parse_events(value, flows_by_id):
    if value.__class__ is not list:
        raise Bad("events not list")
    if len(value) > 20000:
        raise Bad("events size")
    events = []
    total = 0
    for ev in value:
        if ev.__class__ is not dict:
            raise Bad("event not object")
        op = ev.get("op")
        if op.__class__ is not str:
            raise Bad("event op")
        if op == "packet":
            if set(ev) != {"op", "flow", "header", "payload"}:
                raise Bad("packet keys")
            fid = ev["flow"]
            if fid.__class__ is not str or fid not in flows_by_id:
                raise Bad("packet flow")
            fl = flows_by_id[fid]
            header = _hex_bytes(ev["header"])
            if len(header) != fl.H:
                raise Bad("packet header size")
            payload = _hex_bytes(ev["payload"])
            if len(payload) > 2048:
                raise Bad("packet payload size")
            total += len(header) + len(payload)
            if total > _MAX_PACKET_BYTES:
                raise Bad("packet bytes budget")
            events.append(("packet", fl, header, payload))
        elif op == "put":
            if set(ev) != {"op", "flow", "node"}:
                raise Bad("put keys")
            fid = ev["flow"]
            if fid.__class__ is not str or fid not in flows_by_id:
                raise Bad("put flow")
            fl = flows_by_id[fid]
            node = ev["node"]
            if node.__class__ is not str or node not in fl.nodeset:
                raise Bad("put node")
            events.append(("put", fl, node))
        elif op == "enable" or op == "disable":
            if set(ev) != {"op", "flow"}:
                raise Bad("control keys")
            fid = ev["flow"]
            if fid.__class__ is not str or fid not in flows_by_id:
                raise Bad("control flow")
            events.append((op, flows_by_id[fid], None))
        elif op == "reset":
            if set(ev) != {"op"}:
                raise Bad("reset keys")
            events.append(("reset", None, None))
        else:
            raise Bad("unknown op")
    return events


def _packet_result(fl, header, payload, enabled):
    if not enabled:
        mode = "ip"
        reason = "disabled"
    else:
        hval = int.from_bytes(header, "big")
        if (hval & fl.kmask) != fl.tmplm:
            mode = "ip"
            reason = "mismatch"
        elif header[fl.qpos] > 7:
            mode = "ip"
            reason = "qos"
        else:
            mode = "mpls"
            reason = "compressed"

    ttl = header[fl.tpos]
    nlinks = fl.N
    if ttl:
        if ttl > nlinks:
            links = nlinks
        else:
            links = ttl
    else:
        links = 0
    plen = len(payload)

    if mode == "ip":
        payload_hex = payload.hex()
        header_hex = header.hex()
        cut = fl.tpos * 2
        pre = header_hex[:cut]
        post = header_hex[cut + 2:]
        wire = [pre + "%02x" % (ttl - i) + post + payload_hex
                for i in range(links)]
        hops = links * (fl.H + plen)
        delivered = wire[-1] if links == nlinks else None
    else:
        tc = header[fl.qpos]
        if fl.nd == 0:
            residue = b""
        elif fl.nd == 1:
            residue = header[fl.dpos0:fl.dpos0 + 1]
        else:
            residue = bytes(fl.dget(header))
        residue_hex = residue.hex()
        payload_hex = payload.hex()
        labelwords = fl.labelwords
        tc9 = tc << 9
        wire = []
        push = wire.append
        for i in range(links):
            push("%08x" % (labelwords[i] | tc9 | 0x100 | (ttl - i))
                 + residue_hex + payload_hex)
        hops = links * (4 + fl.nd + plen)
        if links == nlinks:
            out = bytearray(fl.tmpl)
            dpos = fl.dpos
            for k in range(fl.nd):
                out[dpos[k]] = residue[k]
            for pos in fl.zpos:
                out[pos] = 0
            out[fl.qpos] = tc
            out[fl.tpos] = ttl - fl.h
            delivered = (bytes(out) + payload).hex()
        else:
            delivered = None
    return {"mode": mode, "reason": reason, "wire": wire,
            "delivered": delivered, "byte_hops": hops}


def _handle_replay(obj):
    if set(obj) != {"mode", "capacities", "flows", "events"}:
        raise Bad("replay keys")
    caps = _parse_caps(obj["capacities"])
    flows, _ = _parse_flows(obj["flows"], caps, True, 512)
    flows_by_id = {fl.id: fl for fl in flows}
    events = _parse_events(obj["events"], flows_by_id)

    tables = {}
    node_count = dict.fromkeys(caps, 0)
    enabled = set()
    results = []
    emit = results.append

    for ev in events:
        op = ev[0]
        if op == "packet":
            fl = ev[1]
            emit(_packet_result(fl, ev[2], ev[3], fl.id in enabled))
        elif op == "put":
            fl = ev[1]
            node = ev[2]
            label = fl.labels[fl.pidx[node]]
            key = (node, label)
            current = tables.get(key)
            if current == fl.id:
                emit(_OK)
            elif current is not None and current in enabled:
                emit(_BUSY)
            elif current is None and node_count[node] >= caps[node]:
                emit(_FULL)
            else:
                if current is None:
                    node_count[node] += 1
                tables[key] = fl.id
                emit(_OK)
        elif op == "enable":
            fl = ev[1]
            if fl.id in enabled:
                emit(_OK)
            else:
                ready = True
                for i in range(fl.N):
                    if tables.get((fl.path[i], fl.labels[i])) != fl.id:
                        ready = False
                        break
                if ready:
                    enabled.add(fl.id)
                    emit(_OK)
                else:
                    emit(_UNREADY)
        elif op == "disable":
            enabled.discard(ev[1].id)
            emit(_OK)
        else:
            enabled.clear()
            emit(_OK)

    entries = [{"node": node, "label": label, "flow": fid}
               for (node, label), fid in tables.items()]
    entries.sort(key=lambda e: (e["node"], e["label"]))
    return {"results": results, "active": sorted(enabled), "tables": entries}


# --------------------------------------------------------------------- plan mode

def _handle_plan(obj):
    if set(obj) != {"mode", "capacities", "flows", "warmup", "pinned",
                    "offers"}:
        raise Bad("plan keys")
    caps = _parse_caps(obj["capacities"])
    flows, _ = _parse_flows(obj["flows"], caps, False, 22)
    warmup = _int_in(obj["warmup"], 0, 1000000000)

    pinned = obj["pinned"]
    if pinned.__class__ is not list:
        raise Bad("pinned not list")
    pinned_set = set()
    for pid in pinned:
        if pid.__class__ is not str or pid not in {fl.id for fl in flows}:
            raise Bad("pinned flow")
        if pid in pinned_set:
            raise Bad("pinned duplicate")
        pinned_set.add(pid)

    offers = obj["offers"]
    if offers.__class__ is not dict:
        raise Bad("offers not object")
    if set(offers) != {fl.id for fl in flows}:
        raise Bad("offers keys")

    runs_by_index = []
    total_header_bytes = 0
    for fl in flows:
        raw = offers[fl.id]
        if raw.__class__ is not list or len(raw) > 256:
            raise Bad("offers runs")
        runs = []
        flow_total = 0
        for run in raw:
            if run.__class__ is not dict or set(run) != {"header", "count"}:
                raise Bad("run keys")
            header = _hex_bytes(run["header"])
            if len(header) != fl.H:
                raise Bad("run header size")
            count = _int_in(run["count"], 1, 1000000000)
            total_header_bytes += len(header)
            flow_total += count
            runs.append((header, count))
        if flow_total > 1000000000:
            raise Bad("run count total")
        runs_by_index.append(runs)
    if total_header_bytes > 65536:
        raise Bad("run header bytes budget")

    return _plan_solve(flows, caps, warmup, pinned_set, runs_by_index)


def _plan_solve(flows, caps, warmup, pinned_set, runs_by_index):
    count = len(flows)
    benefit = [0] * count
    for i, fl in enumerate(flows):
        per_packet = (fl.H - 4 - fl.nd) * fl.N
        if per_packet <= 0:
            continue
        kmask = fl.kmask
        tmplm = fl.tmplm
        qpos = fl.qpos
        tpos = fl.tpos
        hops = fl.h
        eligible = 0
        seen = 0
        for header, packets in runs_by_index[i]:
            if ((int.from_bytes(header, "big") & kmask) == tmplm
                    and header[qpos] <= 7 and header[tpos] > hops):
                end = seen + packets
                if end > warmup:
                    start = seen if seen > warmup else warmup
                    eligible += end - start
            seen += packets
        benefit[i] = per_packet * eligible

    users = {node: [] for node in caps}
    for i, fl in enumerate(flows):
        for node in fl.path:
            users[node].append(i)

    for node, members in users.items():
        used = 0
        for i in members:
            if flows[i].id in pinned_set:
                used += 1
        if used > caps[node]:
            return {"infeasible": True}

    candidates = [i for i in range(count)
                  if benefit[i] > 0 and flows[i].id not in pinned_set]
    candidates.sort(key=lambda i: (-benefit[i], flows[i].id))
    pinned_benefit = 0
    pinned_count = 0
    for i in range(count):
        if flows[i].id in pinned_set:
            pinned_benefit += benefit[i]
            pinned_count += 1

    binding = [node for node in caps if caps[node] < len(users[node])]
    bindex = {node: b for b, node in enumerate(binding)}
    nb = len(binding)
    m = len(candidates)

    if m == 0 or nb == 0:
        chosen = list(candidates)
    else:
        capb = [caps[node] for node in binding]
        uses = []
        for i in candidates:
            fl = flows[i]
            uses.append(tuple(bindex[node] for node in fl.path
                              if node in bindex))
        rem = [[0] * (m + 1) for _ in range(nb)]
        for j in range(m - 1, -1, -1):
            for b in range(nb):
                rem[b][j] = rem[b][j + 1]
            for b in uses[j]:
                rem[b][j] += 1
        rel = []
        for j in range(m):
            entry = []
            for b in range(nb):
                if rem[b][j]:
                    entry.append((b, rem[b][j]))
            rel.append(entry)
        relidx = [tuple(b for b, _ in entry) for entry in rel]
        suffix = [0] * (m + 1)
        cand_benefit = [benefit[i] for i in candidates]
        for j in range(m - 1, -1, -1):
            suffix[j] = suffix[j + 1] + cand_benefit[j]
        base = [0] * nb
        for i in range(count):
            if flows[i].id in pinned_set:
                for node in flows[i].path:
                    b = bindex.get(node)
                    if b is not None:
                        base[b] += 1
        scale = count + 1

        usage = list(base)
        memo = {}
        choice = {}

        def search(j):
            if j == m:
                return 0
            key = (j, bytes([usage[b] for b in relidx[j]]))
            cached = memo.get(key)
            if cached is not None:
                return cached
            rest = m - j
            limit = rest
            for b, rv in rel[j]:
                avail = capb[b] - usage[b] + rest - rv
                if avail < limit:
                    limit = avail
            if limit <= 0:
                memo[key] = 0
                choice[key] = 0
                return 0
            upper = (suffix[j] - suffix[j + limit]) * scale - limit
            best = 0
            pick = 0
            touched = uses[j]
            feasible = True
            for b in touched:
                if usage[b] >= capb[b]:
                    feasible = False
                    break
            if feasible:
                for b in touched:
                    usage[b] += 1
                value = cand_benefit[j] * scale - 1 + search(j + 1)
                for b in touched:
                    usage[b] -= 1
                if value > best:
                    best = value
                    pick = 1
            if best >= upper:
                memo[key] = best
                choice[key] = pick
                return best
            value = search(j + 1)
            if value > best:
                best = value
                pick = 0
            memo[key] = best
            choice[key] = pick
            return best

        search(0)

        chosen = []
        usage = list(base)
        for j in range(m):
            key = (j, bytes([usage[b] for b in relidx[j]]))
            if choice.get(key) == 1:
                chosen.append(candidates[j])
                for b in uses[j]:
                    usage[b] += 1

        # safety re-verification of the reconstructed admission set
        verify_usage = {node: 0 for node in caps}
        ok = True
        for i in range(count):
            if flows[i].id in pinned_set:
                for node in flows[i].path:
                    verify_usage[node] += 1
        for i in chosen:
            for node in flows[i].path:
                verify_usage[node] += 1
        for node, used in verify_usage.items():
            if used > caps[node]:
                ok = False
                break
        gained = sum(benefit[i] for i in chosen)
        if not ok or (pinned_benefit + gained) * scale - (
                pinned_count + len(chosen)) != search(0):
            chosen = _plan_bruteforce(candidates, benefit, flows, caps,
                                      pinned_set, pinned_benefit,
                                      pinned_count)

    selected = sorted([flows[i].id for i in chosen])
    selected += [fl.id for fl in flows if fl.id in pinned_set]
    selected.sort()
    saved = pinned_benefit + sum(benefit[i] for i in chosen)
    return {"selected": selected, "saved": saved}


def _plan_bruteforce(candidates, benefit, flows, caps, pinned_set,
                     pinned_benefit, pinned_count):
    """Exact fallback search returning the chosen candidate list."""
    m = len(candidates)
    cap_list = [caps[node] for node in caps]
    node_pos = {node: i for i, node in enumerate(caps)}
    uses = []
    for i in candidates:
        uses.append(tuple(node_pos[node] for node in flows[i].path))
    base = [0] * len(cap_list)
    for fl in flows:
        if fl.id in pinned_set:
            for node in fl.path:
                base[node_pos[node]] += 1
    scale = len(flows) + 1
    suffix = [0] * (m + 1)
    for j in range(m - 1, -1, -1):
        suffix[j] = suffix[j + 1] + benefit[candidates[j]]
    best_score = pinned_benefit * scale - pinned_count
    best_set = []
    state = {"score": best_score, "set": best_set}
    usage = list(base)
    current = []

    def walk(j, ben, cnt):
        rest = m - j
        limit = rest
        for pos in range(len(cap_list)):
            avail = cap_list[pos] - usage[pos] + rest - remaining[j][pos]
            if avail < limit:
                limit = avail
        if limit <= 0:
            limit = 0
        upper = (ben + suffix[j] - suffix[j + limit]) * scale - (cnt + limit)
        if upper <= state["score"]:
            return
        if j == m:
            score = ben * scale - cnt
            if score > state["score"]:
                state["score"] = score
                state["set"] = list(current)
            return
        touched = uses[j]
        feasible = True
        for pos in touched:
            if usage[pos] >= cap_list[pos]:
                feasible = False
                break
        if feasible:
            for pos in touched:
                usage[pos] += 1
            current.append(candidates[j])
            walk(j + 1, ben + benefit[candidates[j]], cnt + 1)
            current.pop()
            for pos in touched:
                usage[pos] -= 1
        walk(j + 1, ben, cnt)

    remaining = []
    for j in range(m + 1):
        row = [0] * len(cap_list)
        for pos in range(len(cap_list)):
            c = 0
            for k in range(j, m):
                if pos in uses[k]:
                    c += 1
            row[pos] = c
        remaining.append(row)
    if m:
        walk(0, pinned_benefit, pinned_count)
    return state["set"]


# ---------------------------------------------------------------------- driver

def _respond(line):
    obj = _load_object(line)
    mode = obj.get("mode")
    if mode == "replay":
        return _handle_replay(obj)
    if mode == "plan":
        return _handle_plan(obj)
    raise Bad("bad mode")


def main():
    out = sys.stdout.buffer
    inp = sys.stdin.buffer
    write = out.write
    dumps = json.dumps
    for raw in inp:
        try:
            if len(raw) > _MAX_LINE:
                raise Bad("line too long")
            line = raw.decode("utf-8")
            response = _respond(line)
        except Bad:
            response = _INPUT_ERROR
        except Exception:
            response = _INPUT_ERROR
        write(dumps(response, separators=(",", ":")).encode("ascii"))
        write(b"\n")
    try:
        out.flush()
    except Exception:
        pass


if __name__ == "__main__":
    main()
